    public void setBowAndStringRotation(float bow, float string) {
        this.armLeftMain.yRot = Trig.toRadians(-bow);
        this.armRightMain.yRot = Trig.toRadians(bow);
        this.stringLeft.yRot = Trig.toRadians(-string);
        this.stringRight.yRot = Trig.toRadians(string);
    }

    public void setTurretRotation(float yaw, float pitch) {
        this.armMain.yRot = Trig.toRadians(yaw);
        this.armMain.xRot = Trig.toRadians(pitch);
    }

    public void setCrankRotations(float angle) {
        this.crankAxle.xRot = Trig.toRadians(angle);
    }

    public void setTriggerAngle(float angle) {
        this.trigger1.xRot = Trig.toRadians(angle);
    }
